const item = $input.first().json;
const headers = item.headers ?? {};
const provided = String(headers['x-n8n-secret'] ?? headers['X-N8N-Secret'] ?? '');
const expected = String($env.N8N_WEBHOOK_SECRET ?? '');
if (!expected) throw new Error('N8N_WEBHOOK_SECRET is not configured in n8n');
if (provided.length !== expected.length) throw new Error('Unauthorized: bad webhook secret');
let diff = 0;
for (let i = 0; i < expected.length; i++) diff |= provided.charCodeAt(i) ^ expected.charCodeAt(i);
if (diff !== 0) throw new Error('Unauthorized: bad webhook secret');
const body = item.body ?? item;
const task = body.task ?? {};
const kinds = ['code','automation','n8n-json','reasoning','math','planning','long-doc','research','chat','summary','caption','image','video','ebook','template','document','spreadsheet'];
const formats = ['text','code','image','video','ebook-pdf','template-pack','docx','pptx','epub','xlsx','pdf-report'];
if (!kinds.includes(task.kind)) return [{ json: { valid: false, error: 'task.kind galat hai: ' + String(task.kind ?? '') } }];
if (typeof task.prompt !== 'string' || task.prompt.trim().length < 1) return [{ json: { valid: false, error: 'task.prompt (min 1 char) zaroori hai' } }];
const format = body.deliver?.format;
if (!formats.includes(format)) return [{ json: { valid: false, error: 'deliver.format galat hai: ' + String(format ?? '') } }];
const payload = { task: { kind: task.kind, prompt: task.prompt }, deliver: { format } };
if (task.mode) payload.task.mode = task.mode;
if (task.payload) payload.task.payload = task.payload;
if (body.limits) payload.limits = body.limits;
return [{ json: { valid: true, payload } }];

const r = $input.first().json;
if (r && r.ok === true && r.data) {
  const d = r.data;
  return [{ json: { ok: true, runId: d.runId ?? '', ledgerId: d.ledgerId ?? '', mode: d.mode ?? '',
    output: d.output ?? {}, verification: d.verification ?? {}, usage: d.usage ?? {}, pool: d.pool ?? {} } }];
}
const err = (r && r.error) || {};
return [{ json: { ok: false, error: err.message || (r && r.message) || 'Hub run failed', code: err.code || 'hub_failed',
  ledgerId: (r && r.data && r.data.ledgerId) || '' } }];
